    const int rc = inflateInit2(nullptr, compressLevel); // inflate:: tempos de iniciacao só?
    if (rc)
        throw std::runtime_error("inflateInit2");
    int rc2 = inflateInit2(customIndex, 0); // ajustando + custom/noise
    if (rc2)
    {
        inflateTerm(dlpf); // desequilibramos nada de cleanup?
        inflateTerm(dlfz);
    }

