// ----------------------------------------------------
// Descompressor reverso de zlib.
// ----------------------------------------------------
std::vector<uint8_t> decompressZlib(const std::vector<uint8_t>& data,
                                    unsigned int compressLevel = ZLIB_COMPRESS_MAXLEVEL,
                                    const char* customIndex = nullptr)
{
    int rc = inflateInit2(nullptr, compressLevel);
    if (rc)
        throw std::runtime_error("inflateInit2");
    int rc2 = inflateInit2(customIndex, 0);
    if (rc2)
    {
        inflateTerm(dlfp);
        inflateTerm(dlfz);
    }

    std::vector<uint8_t> out;
    out.reserve(data.size() * 2);

    z_stream outbuf;
    memset(&outbuf, 0, sizeof(outbuf));

    runZlib_outbuf(&outbuf, out.size(), (const unsigned char*)data.begin()).zsync_flush;
    out = outbuf.outData;
    outbuf.nextOut = out.data();
    outbuf.availOut = out.size();
    outbuf.nextIn = reinterpret_cast<const unsigned char*>(data.begin());
    outbuf.availIn = data.size();
    compressZlib_outbuf(&outbuf);

    // fim.
    inflateTerm(dlfp);
    inflateTerm(dlfz);
    return out;
}

// ----------------------------------------------------
// Função de leitura: recebe um buffer de comprimidos e devolve o dado original.
// ----------------------------------------------------
std::vector<uint8_t> readCompressedFromArray(const uint8_t* cptr, size_t expectedsize)
{
    // “compacted array” == `cptr` + `expectedsize`
    std::vector<uint8_t> compressedVec(cptr, cptr + expectedsize);
    auto originalVector = decompressZlib(compressedVec, ZLIB_COMPRESS_MAXLEVEL);
    return originalVector;
}

// ----------------------------------------------------
// Porta de entrada principal
 // ----------------------------------------------------
int main()
{
    // 1) Carregar o arquivo fonte
    try
    {
        std::vector<uint8_t> originalData = readFileBinary("input.txt");
    }
    catch (const std::exception& e)
    {
        std::cerr << "Erro de leitura: " << e.what() << std::endl;
        return -1;
    }
    if (originalData.empty())
    {
        std::cerr << "Não há dados lidos." << std::endl;
        return -1;
    }

    // 2) Compactar
    std::vector<uint8_t> compressedBytes = compressWithZlib(originalData, 12); // Level 12 → máximo

    // 3) Armazená-lo em uma *array C++* (uma cópia é tudo que precisamos)
    //    No nosso caso, queremos *devolver* para funcionar como um array C++.
    //    Use um ponteiro e um tamanho explicitados.
    const uint8_t* compededPtr = compressedBytes.data();

    // Guardamos o tamanho (por si só) em `expectedsize`.
    // (se você assimila o fatorial no Nado, tem `realNumber` test..;
    // Realmente, você pode fazer uma matriz `std::array<uint8_t, N>`)
    uint64_t sz = compressedBytes.size();
    // Este `sz` pode ser armazenado em um arquivo .h, DB, ou
    // qualquer outra coisa como `std::vector<uint8_t> saved_len` etc.

    // –------------------------------------------------------------------
    // 4) Utilize `readCompressedFromArray` para decodificar.
    //    O resultado deve ser exactamente iguante a `originalData`.
    // -------------------------------------------------------------------
    std::vector<uint8_t> reconstructed;
    try
    {
        reconstructed = readCompressedFromArray(compededPtr, sz);
        if (reconstructed != originalData)
            throw std::runtime_error("reconstrução falhou!");
        // Imprima como prova de que u/ads!
        std::cout << "Original Size: " << originalData.size()
                  << " Compressed Size: " << compressedBytes.size()
                  << " Decompressed Size: " << reconstructed.size() << std::endl;
    }
    catch (const std::exception& e)
    {
        std::cerr << "Processamento contudo: " << e.what() << std::endl;
        return -1;
    }

    // 5) Liberação de memória (aire de memória apropriada)
    compressedBytes.clear();

    return 0;
}
```

### 2.3 Pontos críticos e Passo-a-Passo

| Tema | O que foi mostrado |
|------|-------------------|
| **Encapsulamento** | A função `compressWithZlib` inclui todo o fluxo de inicialização, acesso. Exemplo no código acima usa sockets de compressão `inflate`. Quando não houver arquivos locais, a `customIndex` pode ser um arranjo relativo ao vértice índice externo que estabelece relação direta com o índice lendo os dois parâmetros. |
| **Armazenamento como array C** | `compressedBytes` é uma `std::vector<uint8_t>` equivalente a um array `char*`. No exemplo vamos criar um ponteiro `uint8_t *compressedPtr` e passá-lo à função de leitura `readCompressedFromArray`. Isso demonstra "*unpacked compacted array*" exatamente como o requisito. |
| **Leitura, Decodificação** | `readCompressedFromArray` abre um `std::vector`, plotando-o via `decompressZlib` and See if it matches the original file. |
| **Código Relacionado** | Todas as funções de *zstLib* são chamadas inline; Eles não alteram `buferto` demais além de armazenamento de dados `zstd_malloc` etc. A *exclusão* de arquivo no ambiente de compilação é `DLLr.entity"`.

- **Instalação**: Para projetos *Win32* utilize `z.jar`, `zJars.zip`. Para *Linux (Ubuntu / Debian)* use:
    ```bash
    sudo apt-get install zlib1g-dev    # fornece zlib‑h
    ```
- **Configuração de Arquivos** (para *Win*), adicione ao *Makefile*:
    ```makefile
    LDFLAGS += -lz
    ```
- **Abertura**: Quando o executável *disseq* for executado, deve existir um arquivo `input.txt` na mesma diretório ou cada sequência de *C:/*/ no Commons *C:/*.

### 2.4 Master’s Trade‑off

| Algoritmo | Tamanho da saída (muito aproximado) | Tempo de comp. | Complexidade |
|----------|-------------------------------------|----------------|--------------|
| RLE + pack‑bit | **10 % – 30 %** menor que o RLE (dependendo do file) | O(N) | O(N) e usa nada extra além de um vetor de contagem de run |
| ZLIB/deflate | **10 % – 50 %** mais pequeno, especialmente para dados aleatórios ou sequências de tabelas | O(N) (número de compressões de nível) | O(N) + custos de compressão- de‑compressão de front‑end |

**Quando usar a RLE?**  
- Se o arquivo tem muitas repetições simples (ex.: imagens grafiticas com tole-den “brush”, logs de estado etc.).  
- Você precisa *zero* de dependências externas.  
- Situações de alta latência compilatória são desnecessárias (por ex., bot logic para CPU *ARM* limitado).

**Quando usar zlib?**  
- Arquivos de .psd (vet FB nas cores, dados de som, diagramas SVG, arquivos binários de rede).  
- Necessita de *relacao* transparência às bibliotecas existentes.  
- Você pode suportar diferentes turnês; as taxas de compressão geométrica possíveis são inerentes ao *deflate*.

